int _pass = 0;
int _fail = 0;

void _test(int num, int got, int expected) {
    bool passed = got == expected;
    std::cout << "---------------------\n";
    std::cout << "Test " << num << ":\n";
    std::cout << (passed ? "Pass" : "Fail") << "\n";
    if (passed) _pass++; else _fail++;
}

int main() {
    FSizeArr<int, 3> tester1 = {1, 2, 3};
    FSizeArr<char> tester2 = {'c', 'd'};
    FSizeArr<int> tester3;
    tester3.data[0] = 1;
    _test(1, 3, tester1.length);
    _test(2, 100, static_cast<int>(tester2.data[1]));
    _test(3, 1, tester3.data[0]);
    _test(2, 3, tester1.data[2]);
    std::cout << "---------------------\n";
    std::cout << _pass << " passed, " << _fail << " failed\n";
    return 0;
}
